      GraphQLEngineBuilder server, Set<Argument> arguments, ResolvedQuery resolvedQuery) {
    return new DataFetcher<java.util.concurrent.CompletableFuture<Object>>() {
      @Override
      public java.util.concurrent.CompletableFuture<Object> get(DataFetchingEnvironment env) {
        java.util.concurrent.CompletableFuture<Object> future = new java.util.concurrent.CompletableFuture<>();
        Set<Argument> argumentSet =
            env.getArguments().entrySet().stream()
